def goreli_parlaklik(hex_renk):
    h = hex_renk.lstrip("#")
    kanallar = [int(h[i:i+2], 16) / 255 for i in (0, 2, 4)]
    duz = [c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4 for c in kanallar]
    r, g, b = duz
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def kontrast(on, arka):
    l1, l2 = goreli_parlaklik(on), goreli_parlaklik(arka)
    ust, alt = max(l1, l2), min(l1, l2)
    return (ust + 0.05) / (alt + 0.05)

for on, arka in [("#767676", "#FFFFFF"), ("#949494", "#FFFFFF"), ("#FFFFFF", "#0F172A")]:
    o = kontrast(on, arka)
    print(on, "/", arka, "->", round(o, 2), "| normal metin AA:", o >= 4.5, "| buyuk metin AA:", o >= 3.0)

from math import ceil, sqrt, factorial

Z_ALFA, Z_BETA = 1.96, 0.84          # cift yonlu %5, guc %80

def orneklem_oran(p1, p2):
    pbar = (p1 + p2) / 2
    return ceil(2 * (Z_ALFA + Z_BETA) ** 2 * pbar * (1 - pbar) / (p2 - p1) ** 2)

def cohen_d(m1, m2, s):
    return abs(m1 - m2) / s

def orneklem_ortalama(d):
    return ceil(2 * (Z_ALFA + Z_BETA) ** 2 / d ** 2)

print("A/B (0.70 -> 0.78) grup basina n :", orneklem_oran(0.70, 0.78))
print("A/B (0.70 -> 0.85) grup basina n :", orneklem_oran(0.70, 0.85))
